 event_payload:=jsonb_build_object('draft_evidence_id',bridge_id,'review_evidence_id',p_review,'source_document_id',source.source_document_id,'business_document_id',business_id,'journal_entry_id',draft->>'journal_entry_id','mapping_snapshot_id',mapping.mapping_snapshot_id,'status','DRAFT');
