 INSERT INTO outbox_event(tenant_id,entity_id,aggregate_type,aggregate_id,event_type,payload,payload_hash) VALUES(p_tenant,p_entity,'BUSINESS_DOCUMENT',business_id,'WBS_PROPERTY_RENT_DRAFT_CREATED',event_payload,refs_jsonb_hash(event_payload));
 response:=event_payload||draft||jsonb_build_object('idempotent',false,'can_submit',true,'can_review',false,'can_approve',false,'can_post',false);UPDATE idempotency_receipt SET status='SUCCEEDED',response_status=201,response_body=response,completed_at=clock_timestamp() WHERE idempotency_receipt_id=idem.idempotency_receipt_id;RETURN response;
